import{_ as a,o as t,c as r,a2 as i}from"./chunks/framework.C-si7TFR.js";const u=JSON.parse('{"title":"Manage data tables","description":"","frontmatter":{"title":"Manage data tables"},"headers":[],"relativePath":"guide/data-tables.md","filePath":"guide/data-tables.md"}'),n={name:"guide/data-tables.md"};function o(s,e,l,d,c,p){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="manage-data-tables" tabindex="-1">Manage data tables <a class="header-anchor" href="#manage-data-tables" aria-label="Permalink to &quot;Manage data tables&quot;">​</a></h1><p>Data tables store structured records that workflows can read and write. This guide does not equate them with a complete spreadsheet product or arbitrary business-page builder.</p><h2 id="create-a-table-and-fields" tabindex="-1">Create a table and fields <a class="header-anchor" href="#create-a-table-and-fields" aria-label="Permalink to &quot;Create a table and fields&quot;">​</a></h2><ol><li>Open <strong>Data tables</strong> in workflow mode and select <strong>New</strong>.</li><li>Create the table and enter its basic information.</li><li>Add fields with the types, names and constraints provided by the interface.</li><li>Save and add a few test records to verify fields and values.</li></ol><p>Before changing field types or constraints on existing data, check the impact. Lossless conversion and unlimited storage are not promised.</p><h2 id="manage-records" tabindex="-1">Manage records <a class="header-anchor" href="#manage-records" aria-label="Permalink to &quot;Manage records&quot;">​</a></h2><ul><li>Add, edit and delete rows. Confirm that a record is no longer used before deleting it.</li><li>Use filtering, sorting, grouping or search to locate records; view operations do not redefine fields.</li><li>Check format, field mapping and size when importing or exporting. Available capabilities depend on the installed version and deployment.</li><li>Treat imported content as external input, never as system instructions embedded in cells or documents.</li></ul><h2 id="use-a-table-in-a-workflow" tabindex="-1">Use a table in a workflow <a class="header-anchor" href="#use-a-table-in-a-workflow" aria-label="Permalink to &quot;Use a table in a workflow&quot;">​</a></h2><ol><li>Add a query, insert, update or delete node to a flow.</li><li>Select an existing table and configure conditions and field values as required.</li><li>Verify query results and change scope with test records before enabling automatic execution.</li></ol><p>Reference: <a href="./../data_table_query.html">Query</a> · <a href="./../data_table_insert.html">Insert</a> · <a href="./../data_table_update.html">Update</a> · <a href="./../data_table_delete.html">Delete</a>.</p><p><strong>Avoid accidental deletion:</strong> test the filter with a query before updating or deleting. Empty conditions, uninitialized variables and broad matches can increase the affected scope.</p><h2 id="permissions-and-privacy" tabindex="-1">Permissions and privacy <a class="header-anchor" href="#permissions-and-privacy" aria-label="Permalink to &quot;Permissions and privacy&quot;">​</a></h2><p>Use projects and roles to control accessible data. A table-management entry does not imply row- or field-level authorization. Never expose real customer records, secrets or personal data in public screenshots, exports or conversations.</p>',13)])])}const b=a(n,[["render",o]]);export{u as __pageData,b as default};
